// AVANT (style ancien) : on teste, PUIS on convertit a la main.
Object obj = "bonjour";
if (obj instanceof String) {
    String s = (String) obj;   // cast manuel, repetitif
    System.out.println(s.length());
}

// APRES (pattern matching pour instanceof, Java 16+) :
// 's' est declaree ET deja convertie si le test reussit.
if (obj instanceof String s) {
    System.out.println(s.length()); // on utilise 's' directement
}

// Une cascade typique : fonctionnelle, mais lourde et facile a rater.
static String decrire(Object obj) {
    if (obj instanceof Integer i) {
        return "un entier : " + i;
    } else if (obj instanceof String s) {
        return "un texte de " + s.length() + " caracteres";
    } else if (obj instanceof Double d) {
        return "un decimal : " + d;
    } else {
        return "type inconnu";
    }
}
// Dans les prochaines lecons, on reecrit ca avec un switch, bien plus clair.

