// La cascade de la lecon precedente, reecrite en switch sur le type.
static String decrire(Object obj) {
    return switch (obj) {
        case Integer i -> "un entier : " + i;
        case String s  -> "un texte de " + s.length() + " caracteres";
        case Double d   -> "un decimal : " + d;
        default         -> "type inconnu";
    };
}
