// Plusieurs branches sur Integer, departagees par des gardes when.
static String signe(Object obj) {
    return switch (obj) {
        case Integer i when i > 0  -> "entier positif : " + i;
        case Integer i when i < 0  -> "entier negatif : " + i;
        case Integer i             -> "entier nul (zero)";
        default                    -> "pas un entier";
    };
}
// signe(7) -> "entier positif : 7"
// signe(-3) -> "entier negatif : -3"
// signe(0) -> "entier nul (zero)"

