// Variante 1 : null a son propre traitement, distinct du default.
static String longueur(String s) {
    return switch (s) {
        case null       -> "aucune chaine (null)";
        case ""         -> "chaine vide";
        default         -> s.length() + " caracteres";
    };
}

// Variante 2 : null et le reste partagent le meme comportement.
static String etiquette(Object obj) {
    return switch (obj) {
        case Integer i      -> "entier : " + i;
        case String s       -> "texte : " + s;
        case null, default  -> "ni entier ni texte (ou null)";
    };
}

