// Hierarchie scellee : les seules formes possibles sont Cercle, Carre, Triangle.
sealed interface Forme permits Cercle, Carre, Triangle { }
record Cercle(double rayon) implements Forme { }
record Carre(double cote) implements Forme { }
record Triangle(double base, double hauteur) implements Forme { }

static double aire(Forme f) {
    // Pas de default : les trois cas couvrent TOUT l'ensemble scelle.
    return switch (f) {
        case Cercle c   -> Math.PI * c.rayon() * c.rayon();
        case Carre ca   -> ca.cote() * ca.cote();
        case Triangle t -> (t.base() * t.hauteur()) / 2;
    };
}

sealed interface Paiement permits Carte, Especes, Virement { }
record Carte(String numero) implements Paiement { }
record Especes(double montant) implements Paiement { }
record Virement(String iban) implements Paiement { }

// Version cascade : lourde, et aucun controle d'exhaustivite.
static String libelle(Paiement p) {
    if (p instanceof Carte c) {
        return "Carte se terminant par " + c.numero();
    } else if (p instanceof Especes e) {
        return "Especes : " + e.montant() + " euros";
    } else if (p instanceof Virement v) {
        return "Virement vers " + v.iban();
    }
    // On est oblige de rajouter ce return "au cas ou", meme s'il est inutile.
    throw new IllegalStateException("paiement inconnu");
}

// Version switch : concise, exhaustive (type scelle), null gere proprement.
static String libelle(Paiement p) {
    return switch (p) {
        case null                       -> "aucun paiement";
        case Carte c                    -> "Carte se terminant par " + c.numero();
        case Especes e when e.montant() > 1000 -> "Gros paiement especes a verifier";
        case Especes e                  -> "Especes : " + e.montant() + " euros";
        case Virement v                 -> "Virement vers " + v.iban();
    };
}
// Pas de default : si on ajoute un type a Paiement, ce switch ne compilera plus.
// La garde when departage les gros paiements especes des petits.

